import json

# Call 1: search for the ss_demos pending sheet
try:
    r1 = tools.mcp__world__api_search(q="ss_demos ws_pending demo requests NDA")
    print("=== SEARCH 1: ss_demos ===")
    print(json.dumps(r1, indent=2, default=str)[:3000])
except Exception as e:
    print(f"mcp__world__api_search not directly reachable: {type(e).__name__}: {e}")
    # Fallback: use the HTTP bridge we know works
    import urllib.request, urllib.error
    URL = "http://127.0.0.1:40573/mcp/8c8cd025520b9d2ccce73b7847cc21f4"
    SESSION = {"id": None}
    _id = {"i": 200}
    def mcp_call(name, args):
        _id["i"] += 1
        req = urllib.request.Request(URL, data=json.dumps({"jsonrpc":"2.0","id":_id["i"],"method":"tools/call","params":{"name":name,"arguments":args}}).encode(),
            headers={"Content-Type":"application/json","Accept":"application/json, text/event-stream","MCP-Session-Id":SESSION["id"] or ""})
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                sid = r.headers.get("MCP-Session-Id")
                if sid: SESSION["id"] = sid
                text = r.read().decode()
        except urllib.error.HTTPError as e:
            return {"HTTPError": str(e.code)}
        data = [l[5:].strip() for l in text.splitlines() if l.startswith("data:")]
        last = data[-1] if data else text
        j = json.loads(last)
        if "error" in j: return {"_err": json.dumps(j["error"])}
        content = j.get("result", {}).get("content", [])
        txt = "".join([x.get("text","") for x in content] or [""])
        try:
            return json.loads(txt)
        except:
            return txt

    r1 = mcp_call("tools/list", {})
    print("=== tools/list ===")
    print(json.dumps(r1, indent=2, default=str)[:3000])

# Call 2: search for NDA policy sheets
try:
    r2 = tools.mcp__world__api_search(q="NDA policy sheet technical demo")
    print("=== SEARCH 2: NDA policy ===")
    print(json.dumps(r2, indent=2, default=str)[:3000])
except Exception as e2:
